def _edit_distance_ratio(a: str, b: str) -> float:
    """Return normalised Levenshtein distance ratio (0 = identical, 1 = totally different)."""
    if a == b:
        return 0.0
    la, lb = len(a), len(b)
    if la == 0 or lb == 0:
        return 1.0
    # Quick length-ratio check: if lengths differ by >30%, skip expensive DP
    if max(la, lb) / min(la, lb) > 1.3:
        return 1.0
    # Standard DP
    prev = list(range(lb + 1))
    for i in range(1, la + 1):
        curr = [i] + [0] * lb
        for j in range(1, lb + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            curr[j] = min(curr[j - 1] + 1, prev[j] + 1, prev[j - 1] + cost)
        prev = curr
    return prev[lb] / max(la, lb)


